INSERT INTO faqs (id, question, answer, category, status, created_at, updated_at) 
VALUES
(1, 'Apa itu Nadi?', 'Nadi adalah asisten kesehatan personal berbasis kecerdasan buatan (AI) yang membantu Anda menganalisis gejala, mempelajari penyakit melalui kamus medis digital, dan memahami profil risiko kesehatan Anda secara logis.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');2, 'Apakah Nadi adalah pengganti dokter?', 'Tidak. Nadi adalah alat bantu informasi dan edukasi. Hasil analisis Nadi bukan merupakan diagnosis medis. Selalu konsultasikan kondisi Anda dengan tenaga medis profesional.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(3, 'Bagaimana cara kerja Nadi?', 'Nadi menggunakan mesin inferensi probabilistik yang mencocokkan gejala yang Anda input dengan basis data medis yang dikurasi oleh para ahli untuk memberikan kemungkinan kondisi kesehatan yang relevan.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(4, 'Apakah aplikasi Nadi gratis?', 'Ya, fitur utama seperti pemeriksaan gejala dan akses ke Nadi-Pedia (Kamus Medis) tersedia secara gratis untuk membantu aksesibilitas kesehatan masyarakat.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(5, 'Apa arti nama "Nadi"?', 'Nadi melambangkan denyut kehidupan. Kami ingin menjadi aplikasi yang selaras dengan ritme tubuh Anda dan memberikan informasi seakurat detak nadi.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(6, 'Siapa yang mengkurasi data medis di Nadi?', 'Data kami dikurasi dari literatur medis terpercaya, standar internasional (seperti ICD-10), dan divalidasi oleh pakar kesehatan untuk memastikan informasi yang akurat.', 'Umum & Dasar', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(7, 'Seberapa akurat analisis AI Nadi?', 'Analisis Nadi didasarkan pada data medis yang luas, namun keakuratannya bergantung pada kelengkapan gejala yang Anda masukkan. AI kami terus belajar, tetapi tidak boleh dianggap sebagai kebenaran medis mutlak.', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(8, 'Apa yang harus saya lakukan setelah mendapatkan hasil analisis?', 'Ikuti petunjuk "Tindakan Berikutnya" yang disarankan oleh Nadi, seperti menemui dokter spesialis tertentu atau melakukan perawatan mandiri jika kondisinya ringan.', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(9, 'Apakah Nadi bisa mendiagnosis penyakit langka?', 'AI Nadi mencakup ribuan kondisi, termasuk beberapa penyakit langka. Namun, penyakit kompleks memerlukan pemeriksaan fisik dan laboratorium yang tidak bisa dilakukan oleh aplikasi.', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(10, 'Apa itu "Nadi Assess"?', 'Nadi Assess adalah fitur pengecekan gejala interaktif yang menanyakan serangkaian pertanyaan dinamis berdasarkan jawaban Anda sebelumnya untuk mempersempit kemungkinan diagnosis.', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(11, 'Dapatkan Nadi memberikan resep obat?', 'Tidak. Nadi tidak pernah memberikan resep obat. Kami hanya memberikan informasi mengenai penanganan umum yang diakui secara medis.', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(12, 'Apakah lokasi saya memengaruhi analisis AI?', 'Ya, lokasi membantu AI mempertimbangkan faktor lingkungan atau epidemiologi lokal (seperti wabah penyakit tertentu di wilayah Anda).', 'AI & Analisis Gejala', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(13, 'Apa itu Nadi-Pedia?', 'Nadi-Pedia adalah fitur kamus penyakit lengkap yang berisi penjelasan, penyebab, gejala, hingga cara pencegahan berbagai kondisi medis yang bisa Anda baca kapan saja.', 'Nadi-Pedia', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(14, 'Apakah isi Nadi-Pedia selalu diperbarui?', 'Ya, kami memperbarui basis data secara berkala mengikuti perkembangan riset medis terbaru dan perubahan standar kesehatan global.', 'Nadi-Pedia', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(15, 'Bisakah saya mencari penyakit berdasarkan nama ilmiahnya?', 'Tentu. Mesin pencari kami mendukung pencarian baik dengan nama populer (misal: Darah Tinggi) maupun nama medis (misal: Hipertensi).', 'Nadi-Pedia', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(16, 'Apakah informasi di kamus ini bisa dipercaya?', 'Kami menggunakan referensi dari otoritas kesehatan resmi dan jurnal medis terverifikasi sebagai sumber utama konten Nadi-Pedia.', 'Nadi-Pedia', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(17, 'Apakah data kesehatan saya aman?', 'Sangat aman. Kami menggunakan enkripsi tingkat lanjut (TLS saat transit dan enkripsi at-rest) untuk memastikan data medis Anda tidak dapat diakses oleh pihak yang tidak berwenang.', 'Privasi & Keamanan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(18, 'Apakah Nadi menjual data saya ke perusahaan asuransi?', 'Tidak. Kami memiliki kebijakan ketat untuk tidak menjual data pribadi atau data kesehatan Anda kepada pihak ketiga untuk tujuan komersial mereka.', 'Privasi & Keamanan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(19, 'Bisakah saya menghapus data saya secara permanen?', 'Bisa. Nadi mendukung fitur "Right to be Forgotten". Anda dapat menghapus akun dan seluruh riwayat konsultasi melalui menu pengaturan.', 'Privasi & Keamanan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(20, 'Apakah Nadi menggunakan data saya untuk melatih AI?', 'Kami mungkin menggunakan data yang telah di-anonimkan secara permanen (identitas dihapus total) untuk meningkatkan akurasi algoritma kami demi kebaikan pengguna secara luas.', 'Privasi & Keamanan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(21, 'Di mana server Nadi berada?', 'Data kami disimpan di infrastruktur cloud yang memenuhi standar kepatuhan perlindungan data yang ketat (seperti GDPR dan UU PDP).', 'Privasi & Keamanan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(22, 'Bagaimana jika saya tidak sengaja memasukkan gejala yang salah?', 'Anda dapat membatalkan konsultasi tersebut dan memulai yang baru. Hasil analisis bersifat dinamis berdasarkan input terbaru Anda.', 'Penggunaan & Fitur', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(23, 'Apakah saya perlu membuat akun untuk menggunakan Nadi?', 'Anda dapat mengakses sebagian besar informasi di Nadi-Pedia tanpa akun, namun fitur pengecekan gejala dan profil risiko memerlukan pendaftaran untuk hasil yang lebih personal.', 'Penggunaan & Fitur', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(24, 'Dapatkah saya menyimpan hasil analisis untuk ditunjukkan ke dokter?', 'Ya, Anda dapat mengunduh ringkasan hasil analisis dalam format PDF untuk memudahkan diskusi dengan tenaga medis profesional.', 'Penggunaan & Fitur', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(25, 'Apakah Nadi bisa digunakan untuk anak-anak?', 'Anak-anak harus menggunakan aplikasi ini di bawah pengawasan orang tua atau wali. Terdapat opsi "Menganalisis Orang Lain" di dalam aplikasi.', 'Penggunaan & Fitur', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(26, 'Mengapa Nadi menanyakan riwayat merokok atau diabetes?', 'Data tersebut adalah "Faktor Risiko" yang membantu AI menentukan probabilitas penyakit dengan lebih akurat sesuai kondisi tubuh Anda.', 'Penggunaan & Fitur', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(27, 'Apa yang harus saya lakukan jika aplikasi crash?', 'Pastikan Anda menggunakan versi terbaru. Jika masalah berlanjut, silakan hubungi tim dukungan kami melalui email di support@nadi.id.', 'Masalah Teknis & Bantuan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(28, 'Apakah Nadi tersedia dalam versi web?', 'Saat ini kami fokus pada aplikasi mobile, namun fitur Nadi-Pedia dapat diakses melalui situs resmi kami di www.nadi.id.', 'Masalah Teknis & Bantuan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(29, 'Bagaimana cara memberikan masukan atau melaporkan kesalahan medis?', 'Kami sangat menghargai masukan Anda. Gunakan fitur "Feedback" di dalam aplikasi untuk melaporkan ketidaksesuaian informasi.', 'Masalah Teknis & Bantuan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');
(30, 'Bagaimana cara kerja sistem notifikasi di Nadi?', 'Nadi akan memberikan pengingat kesehatan berkala atau pembaruan artikel dari Nadi-Pedia yang relevan dengan profil kesehatan Anda.', 'Masalah Teknis & Bantuan', 'active', '2026-04-18 23:39:14.028', '2026-04-18 23:39:14.028');